/* mimir_alloc.map - MimirAlloc shared-library export contract (E-002).
 *
 * This version script is the machine-readable record of the
 * libmimiralloc.so dynamic export contract: exactly the
 * public entry points declared in include/mimir_alloc.h are
 * exported (four through Z-073; six from Z-074; seven from
 * Z-075, which added mimir_usable_size as an explicit
 * contract change (decision D-012, recorded in
 * tests/abi/recorded_run_z13_z075.txt) after Z-074 added
 * exported (four through Z-073; eight from Z-077 (six from Z-074, which added
 * the two aligned-allocation entry points of the Z-073
 * contract as an explicit contract change, recorded in
 * tests/abi/recorded_run_z13_z074.txt, and two more from
 * Z-077 -- mimir_trim and mimir_reallocarray, recorded in
 * tests/abi/recorded_run_z13_z077.txt); every other symbol
 * defined by the library objects
 * (the internal mimir_core_* and mimir_platform_* functions) is
 * bound locally and never appears in .dynsym as an exported
 * global.
 *
 * The node is deliberately ANONYMOUS (no version name). A named
 * node such as MIMIRALLOC_1.0 would (a) add an ABS version-name
 * symbol to .dynsym, so the defined dynamic-symbol list would
 * no longer be exactly the four public symbols, and (b) imply a
 * symbol-version / ABI-stability promise that the public header
 * expressly withholds: the namespaced API is [UNRESOLVED: U-03]
 * and no symbol-version promise is made (B-008 N-10). A named
 * version node belongs to the future slice that freezes the
 * ABI, not to this one. See docs/SHARED_LIBRARY_BUILD.md.
 */
{
  global:
    mimir_malloc;
    mimir_free;
    mimir_calloc;
    mimir_realloc;
    mimir_aligned_alloc;
    mimir_posix_memalign;
    mimir_usable_size;
    mimir_stats_snapshot;
    mimir_trim;
    mimir_reallocarray;
    mimir_memalign;
    mimir_valloc;
    mimir_pvalloc;
  local:
    *;
};
